					applyThemeColor(entryForSubscription.Key, newColor)
					local t30 = capturedPicker
					local Set4 = t30.Set
					local t31 = { Rgb = newColor, Alpha = 1 }
					Set4(t30, t31, true)
				end

				trove:Connect(config:Changed(configUtil.appendPath(themeConfigPath, entry.Key)), onSavedColorChanged)
			end
		end
	end

