				if key == "Accent" then
					ui.SetAccent(color)
				else
					theme.refresh(key, color)
				end
			end

			local nextThemeEntry = themeEntries
			local entryIndex = nil
			while true do
				local entry
				entryIndex, entry = nextThemeEntry(nil, entryIndex)
				if entryIndex == nil then
					break
				end
				local currentColor = theme.get(entry.Key)
				if config ~= nil then
					local savedColor = config:Get(configUtil.appendPath(themeConfigPath, entry.Key))
					if typeof(savedColor) == "Color3" then
						currentColor = savedColor
					end
				end
				local AddColor2 = themeColorsSection.AddColor
