				local t73 = { Rgb = currentColor, Alpha = 1 }
				colorPickerOptions.Default = t73
				local entryForPicker = entry

				function colorPickerOptions:OnChanged()
					if config == nil then
						applyThemeColor(entryForPicker.Key, self.Rgb)
					else
						config:Set(configUtil.appendPath(themeConfigPath, entryForPicker.Key), self.Rgb)
					end
				end

				local colorPicker = AddColor2(themeColorsSection, colorPickerOptions)
				if config ~= nil then
					local entryForSubscription = entry
					local capturedPicker = colorPicker

					local function onSavedColorChanged(newColor)
						if typeof(newColor) ~= "Color3" then
							return
						end
						applyThemeColor(entryForSubscription.Key, newColor)
						local t74 = capturedPicker
						local Set6 = t74.Set
						local t75 = { Rgb = newColor, Alpha = 1 }
						Set6(t74, t75, true)
					end

					trove:Connect(config:Changed(configUtil.appendPath(themeConfigPath, entry.Key)), onSavedColorChanged)
				end
			end
		end

