	local function finishReplaying(recorder, reason)
		if recorder._state.kind ~= "Replaying" then
			return
		end
		recorder:_TeardownReplay()
		settings:Set(replayStatePath, false)
		if reason == "Diverged" then
			notify("Replay stopped (off course)")
		else
			notify("Finished replaying")
		end
	end

	local function resolveStartContext(recorder)
		local aliveState = recorder._aliveState
		local localState = recorder._duelers.localState
		local innerContext = recorder._playerContext.inner
		local anchor = recorder._currentMap:GetAnchor()
		if aliveState == nil or localState == nil or (innerContext == nil or anchor == nil) then
			notify("You need to be alive and in a match")
			return nil
		end
		local context = {
			aliveState = aliveState,
			duelState = localState,
			innerContext = innerContext,
			mapAnchor = anchor
		}
		return context
	end

	local function startRecordingNow(recorder)
		local startContext = recorder:_ResolveStartContext()
		if startContext == nil then
			return false
		end
		local mapName = startContext.duelState:GetMapName()
		if mapName == nil then
			notify("You need to be alive and in a match")
			return false
		end
		local kind = recorder._state.kind
		if kind ~= "Idle" then
			if kind == "Recording" then
				notify("Already recording")
			elseif kind == "Replaying" then
				notify("Can't record while replaying")
			end
			return false
		end
		local inputReservation = recorder._inputHook:Reserve()
		local motionRecorder = MotionRecorder.new(
			mapName,
			startContext.mapAnchor,
			startContext.aliveState,
			startContext.innerContext.fighterState.inner,
			startContext.innerContext.itemBehaviors,
			inputReservation
		)
		motionRecorder:Update()
		local recordingState = { kind = "Recording", recorder = motionRecorder }
		recorder._state = recordingState
		notify("Now recording")
		return true
	end

	local function teardownRecording(recorder)
		local state = recorder._state
		if state.kind ~= "Recording" then
			return
		end
		state.recorder:Destroy()
		local idleState = { kind = "Idle" }
		recorder._state = idleState
	end

	local function saveLastRecording(recorder, name)
		local lastRecording = recorder._lastRecording
		if lastRecording == nil then
			notify("No recording to save")
			return
		end
		if not recorder._persistence:Save(name, lastRecording).ok then
			notify("Failed to save recording")
			return
