	local function loadBitOps()
		local xorTable = {}
		local andTable = {}
		for hi = 0, 15 do
			for lo = 0, 15 do
				local xorResult = 0
				local andResult = 0
				local bit = 1
				local i = 0
				local bRest = lo
				local aRest = hi
				while true do
					i = i + 1
					if not (i <= 4) then
						break
					end
					local aBit = aRest % 2
					local bBit = bRest % 2
					if aBit ~= bBit then
						xorResult = xorResult + bit
					end
					if aBit == 1 and bBit == 1 then
						andResult = andResult + bit
					end
					aRest = math.floor(aRest / 2)
					bRest = math.floor(bRest / 2)
					bit = bit * 2
				end
				xorTable[hi * 16 + lo] = xorResult
				andTable[hi * 16 + lo] = andResult
			end
		end

		local function bxor(a, b)
			local result = 0
			local place = 1
			for _ = 1, 8 do
				result = result + xorTable[a % 16 * 16 + b % 16] * place
				a = math.floor(a / 16)
				b = math.floor(b / 16)
				place = place * 16
			end
			return result
		end

		local function band(a, b)
			local result = 0
			local place = 1
			for _ = 1, 8 do
				result = result + andTable[a % 16 * 16 + b % 16] * place
				a = math.floor(a / 16)
				b = math.floor(b / 16)
				place = place * 16
			end
			return result
		end

		local function rshift(value, shift)
			return (math.floor(value / 2 ^ shift))
		end

		local function mul32(a, b)
			return (band(
				band(a, 65535) * b + rshift(a, 16) * b % 65536 * 65536,
				4294967295
			))
		end

		local BitOps = { bxor = bxor, band = band, rshift = rshift, mul32 = mul32 }
		return BitOps
	end

