	local function loadMouseHumanizer()
		local MouseHumanizer = {}
		MouseHumanizer.__index = MouseHumanizer
		local pi3 = math.pi

		local function erf(value)
			local sign
			sign = value < 0
			sign = sign and -1 or 1
			local absValue = math.abs(value)
			local erfT = 1 / (1 + 0.3275911 * absValue)
			return sign * (1 - (0.254829592 * erfT - 0.284496736 * erfT * erfT + 1.421413741 * erfT ^ 3 - 1.453152027 * erfT ^ 4 + 1.061405429 * erfT ^ 5) * math.exp(-absValue * absValue))
		end

		local sqrt2 = math.sqrt(2)

		local function normalCdf(z)
			return 0.5 * (1 + erf(z / sqrt2))
		end

		local function lognormalCdf(timeMs, onset, mu, sigma)
			if timeMs <= onset then
				return 0
			end
			return (normalCdf((math.log(timeMs - onset) - mu) / sigma))
		end

		local sqrt2Pi = math.sqrt(2 * pi3)

		local function lognormalPdf(pdfTime, pdfOnset, pdfMu, pdfSigma)
			if pdfTime <= pdfOnset then
				return 0
			end
			local sinceOnset = pdfTime - pdfOnset
			local standardized = (math.log(sinceOnset) - pdfMu) / pdfSigma
			return 1 / (pdfSigma * sqrt2Pi * sinceOnset) * math.exp(-0.5 * standardized * standardized)
		end

		local curvatureNorm = 0.03456

		local function curvatureProfile(progress)
			if progress <= 0 or 1 <= progress then
				return 0
			end
			return progress * progress * (1 - progress) * (1 - progress) * (1 - progress) / curvatureNorm
		end

		local function directionCurvature(angle)
			return 0.5 + 0.8 * math.abs(math.sin(angle)) - 0.15 * math.abs(math.cos(angle))
		end

		local function gaussian(rng, mean, stdDev)
			local u1 = rng:NextNumber()
			local NextNumber4 = rng:NextNumber()
			if u1 < 1e-15 then
				u1 = 1e-15
			end
			return mean + stdDev * (math.sqrt(-2 * math.log(u1)) * math.cos(2 * pi3 * NextNumber4))
		end

		local function gammaSample(gammaRng, shape, scale)
			local shapeBoost = 1
			if shape < 1 then
				shapeBoost = gammaRng:NextNumber() ^ (1 / shape)
				shape = shape + 1
			end
			local gammaD = shape - 0.3333333333333333
			local gammaC = math.sqrt(9 * gammaD)
			while true do
				local normalDraw = gaussian(gammaRng, 0, 1)
				local cube = (1 + 1 / gammaC * normalDraw) ^ 3
				if 0 < cube then
					local uniformDraw = gammaRng:NextNumber()
					if uniformDraw < 1e-15 then
						uniformDraw = 1e-15
					end
					if uniformDraw < 1 - 0.0331 * normalDraw * normalDraw * normalDraw * normalDraw or
						math.log(uniformDraw) < 0.5 * normalDraw * normalDraw + gammaD * (1 - cube + math.log(cube)) then
						return gammaD * cube * scale * shapeBoost
					end
				end
			end
		end

		function MouseHumanizer.new()
			local humanizer = {
				_fittsA = 50,
				_fittsB = 100,
				_target_width = 20,
				_undershoot_min = 0.92,
				_undershoot_max = 0.97,
				_peak_time_ratio = 0.35,
				_primary_sigma_min = 0.18,
				_primary_sigma_max = 0.28,
				_overshoot_prob = 0.15,
				_overshoot_min = 1.02,
				_overshoot_max = 1.08,
				_correction_sigma_min = 0.12,
				_correction_sigma_max = 0.2,
				_second_correction_prob = 0.25,
				_curvature_scale = 0.025,
				_ou_theta = 3.5,
				_ou_sigma = 1.2,
				_tremor_freq_min = 8,
				_tremor_freq_max = 12,
				_tremor_amp_min = 0.15,
				_tremor_amp_max = 0.55,
				_sdn_k = 0.04,
				_sample_dt_mean = 7.8,
				_gamma_shape = 3.5,
				_trajectory = nil,
				_trajectoryIndex = 1,
				_elapsed = 0,
				_lastTargetX = 0,
				_lastTargetY = 0,
				_rng = Random.new()
			}
			return (setmetatable(humanizer, MouseHumanizer))
		end

		function MouseHumanizer:Generate(fromX, fromY, toX, toY)
			local _rng2 = self._rng

			local function uniform(low, high)
				return low + _rng2:NextNumber() * (high - low)
			end

			local function normal(normalMean, normalStdDev)
				return (gaussian(_rng2, normalMean, normalStdDev))
			end

			local dx = toX - fromX
			local dy = toY - fromY
			local distance = math.sqrt(dx * dx + dy * dy)
			local heading = math.atan2(dy, dx)
			if distance < 1 then
				return (table.create(2))
			end
			local dirX = dx / distance
			local dirY = dy / distance
			local fittsIndex = math.log(distance / self._target_width + 1)
			local ln2 = math.log(2)
			local _fittsA2 = self._fittsA
			local _fittsB2 = self._fittsB
			local durationJitter = math.exp(normal(0, 0.08))
			local durationMs = math.max((_fittsA2 + _fittsB2 * (fittsIndex / ln2)) * durationJitter, 80)
			local primaryRatio
			primaryRatio = uniform(0, 1) < self._overshoot_prob
			primaryRatio = primaryRatio and uniform(self._overshoot_min, self._overshoot_max) or
				uniform(self._undershoot_min, self._undershoot_max)
			local primaryDistance = distance * primaryRatio
			local primarySigma = uniform(self._primary_sigma_min, self._primary_sigma_max)
			local peakRatio = uniform(self._peak_time_ratio - 0.03, self._peak_time_ratio + 0.03)
			local primaryMu = math.log(durationMs * peakRatio) + primarySigma * primarySigma
			local corrections = {}
			local remaining = distance - primaryDistance
			local secondSign, correctionSign
			if 0.5 < math.abs(remaining) then
				correctionSign = 0 < remaining
				correctionSign = correctionSign and 1 or -1
				local correctionDistance = math.abs(remaining) * uniform(0.88, 1.02)
				local correctionSigma = uniform(self._correction_sigma_min, self._correction_sigma_max)
				local correctionPeak = uniform(0.12, 0.18)
				local _ = table.insert
				local correction = {
					D = correctionDistance,
					t0 = durationMs * uniform(0.55, 0.68),
					mu = math.log(durationMs * correctionPeak) + correctionSigma * correctionSigma,
					sigma = correctionSigma,
					dirX = dirX * correctionSign,
					dirY = dirY * correctionSign
				}
				table.insert(corrections, correction)
				local residual = remaining - correctionDistance * correctionSign
				if 0.3 < math.abs(residual) and uniform(0, 1) < self._second_correction_prob then
					secondSign = 0 < residual
					secondSign = secondSign and 1 or -1
					local secondDistance = math.abs(residual)
					local secondScale = uniform(0.85, 1.05)
					local secondSigma = uniform(0.1, 0.16)
					local secondPeak = uniform(0.08, 0.12)
					local _ = table.insert
					local secondCorrection = {
						D = secondDistance * secondScale,
						t0 = durationMs * uniform(0.78, 0.88),
						mu = math.log(durationMs * secondPeak) + secondSigma * secondSigma,
						sigma = secondSigma,
						dirX = dirX * secondSign,
						dirY = dirY * secondSign
					}
					table.insert(corrections, secondCorrection)
				end
			end
			local curvature = distance * self._curvature_scale * directionCurvature(heading) * normal(0, 1)
			local tremorFreq = uniform(self._tremor_freq_min, self._tremor_freq_max)
			local tremorAmp = uniform(self._tremor_amp_min, self._tremor_amp_max)
			local tremorPhaseX = uniform(0, 2 * pi3)
			local tremorPhaseY = uniform(0, 2 * pi3)
			local driftX = 0
			local driftY = 0
			local totalMs = durationMs * 1.15
			local _sample_dt_mean2 = self._sample_dt_mean
			local _gamma_shape2 = self._gamma_shape
			local sampleTimes = table.create(1)
			local sampleTime = 0
			while sampleTime < totalMs do
				sampleTime = sampleTime + math.clamp(
					gammaSample(_rng2, self._gamma_shape, _sample_dt_mean2 / _gamma_shape2),
					2,
					25
				)
				if sampleTime <= totalMs + 15 then
					table.insert(sampleTimes, sampleTime)
				end
			end
			local points = {}
			local sampleIndex, stepMs
			while true do
				local sampleMs
				sampleIndex, sampleMs = sampleTimes(nil, sampleIndex)
				if sampleIndex == nil then
					break
				end
				if 1 < sampleIndex then
					stepMs = sampleMs - sampleTimes[sampleIndex - 1]
				else
					stepMs = self._sample_dt_mean
				end
				local stepSeconds = stepMs / 1000
				local primaryProgress = lognormalCdf(sampleMs, 0, primaryMu, primarySigma)
				local posX = fromX + dirX * primaryDistance * primaryProgress + -dirY * curvature * curvatureProfile(primaryProgress)
				local posY = fromY + dirY * primaryDistance * primaryProgress + dirX * curvature * curvatureProfile(primaryProgress)
				local correctionIndex = nil
				while true do
					local activeCorrection
					correctionIndex, activeCorrection = corrections(nil, correctionIndex)
					if correctionIndex == nil then
						break
					end
					local correctionProgress = lognormalCdf(sampleMs, activeCorrection.t0, activeCorrection.mu, activeCorrection.sigma)
					posX = posX + activeCorrection.dirX * activeCorrection.D * correctionProgress
					posY = posY + activeCorrection.dirY * activeCorrection.D * correctionProgress
				end
				local speed = primaryDistance * lognormalPdf(sampleMs, 0, primaryMu, primarySigma)
				local speedIndex = nil
				while true do
					local speedCorrection
					speedIndex, speedCorrection = corrections(nil, speedIndex)
					if speedIndex == nil then
						break
					end
					speed = speed + speedCorrection.D * lognormalPdf(sampleMs, speedCorrection.t0, speedCorrection.mu, speedCorrection.sigma)
				end
				driftX = driftX + (-self._ou_theta * driftX * stepSeconds + self._ou_sigma * math.sqrt(stepSeconds) * normal(0, 1))
				driftY = driftY + (-self._ou_theta * driftY * stepSeconds + self._ou_sigma * math.sqrt(stepSeconds) * normal(0, 1))
				local sampleSeconds = sampleMs / 1000
				local tremorDamping = 1 / (1 + speed * 0.3)
				local tremorX = math.sin(2 * pi3 * tremorFreq * sampleSeconds + tremorPhaseX)
				local tremorY = math.sin(2 * pi3 * tremorFreq * sampleSeconds + tremorPhaseY)
				local _sdn_k3 = self._sdn_k
				local noiseX = normal(0, 1)
				local _sdn_k4 = self._sdn_k
				local noiseY = normal(0, 1)
				local _ = table.insert
				local point = {
					x = posX + driftX + tremorAmp * tremorDamping * tremorX + _sdn_k3 * speed * noiseX,
					y = posY + driftY + tremorAmp * tremorDamping * tremorY + _sdn_k4 * speed * noiseY,
					t = sampleMs
				}
				table.insert(points, point)
			end
			return points
		end

		function MouseHumanizer:_NeedsRegeneration(targetX, targetY)
			if not (self._trajectory and #self._trajectory ~= 0) then
				return true
			end
			local deltaX = targetX - self._lastTargetX
			local deltaY = targetY - self._lastTargetY
			local needsRegen
			needsRegen = 9 < deltaX * deltaX + deltaY * deltaY
			return needsRegen
		end

		function MouseHumanizer.Predict(mover, origin, target, deltaTime)
			local delta = target - origin
			if delta.Magnitude < 1 then
				return delta
			end
			if mover:_NeedsRegeneration(target.X, target.Y) then
				mover._trajectory = mover:Generate(origin.X, origin.Y, target.X, target.Y)
				mover._trajectoryIndex = 1
				mover._elapsed = 0
				mover._lastTargetX = target.X
				mover._lastTargetY = target.Y
			end
			local _trajectory4 = mover._trajectory
			if not (_trajectory4 and not (#_trajectory4 < 2)) then
				return delta
			end
			mover._elapsed = mover._elapsed + deltaTime * 1000
			local pointIndex = mover._trajectoryIndex
			while pointIndex < #_trajectory4 and _trajectory4[pointIndex + 1].t <= mover._elapsed do
				pointIndex = pointIndex + 1
			end
			mover._trajectoryIndex = pointIndex
			if #_trajectory4 <= pointIndex then
				mover._trajectory = nil
				return delta
			end
			local fromPoint = _trajectory4[pointIndex]
			local toPoint = _trajectory4[pointIndex + 1]
			local segmentMs = toPoint.t - fromPoint.t
			local alpha = 1
			if 0 < segmentMs then
				alpha = math.clamp((mover._elapsed - fromPoint.t) / segmentMs, 0, 1)
			end
			return (Vector2.new(
				fromPoint.x + (toPoint.x - fromPoint.x) * alpha - origin.X,
				fromPoint.y + (toPoint.y - fromPoint.y) * alpha - origin.Y
			))
		end

		function MouseHumanizer.ApplyFlickProfile(profiled, flickProfile)
			local flickMs = math.max(flickProfile.durationMs, 20)
			profiled._fittsA = flickMs / 4
			profiled._fittsB = flickMs / 4
			profiled._target_width = 80
			profiled._peak_time_ratio = 0.32
			profiled._primary_sigma_min = 0.2
			profiled._primary_sigma_max = 0.26
			profiled._undershoot_min = 0.97
			profiled._undershoot_max = 1
			profiled._overshoot_prob = 0.08
			profiled._overshoot_min = 1.01
			profiled._overshoot_max = 1.04
			profiled._second_correction_prob = 0
			profiled._correction_sigma_min = 0.1
			profiled._correction_sigma_max = 0.14
			profiled._curvature_scale = math.clamp(flickProfile.curvature, 0, 50) / 1000
