	local function makeWrapPreview_proto(wrapName)
		local function renderPreview(_, tile)
			tile.HideImage()
			local viewportFrame = Instance.new("ViewportFrame")
			viewportFrame.Size = UDim2.fromScale(1, 1)
			viewportFrame.Position = UDim2.fromScale(0.5, 0.5)
			viewportFrame.AnchorPoint = Vector2.new(0.5, 0.5)
			viewportFrame.BackgroundTransparency = 1
			viewportFrame.Parent = tile.Content
			local camera = Instance.new("Camera")
			camera.FieldOfView = 25
			camera.CFrame = previewCameraCFrame
			camera.Parent = viewportFrame
			viewportFrame.CurrentCamera = camera
			local model = wrapPreviewModel:Clone()
			model:PivotTo(CFrame.identity)
			local originals = wrapRenderer.recordOriginalProperties(model)
			wrapRenderer.applyWrap(originals, wrapName)
			model.Parent = viewportFrame
		end

		return renderPreview
	end

	local function buildItemList_proto(nextName, makeRenderer)
		local items = table.clone(specialItems)
		local index, renderer
		while true do
			local name
			index, name = nextName(nil, index)
			if index == nil then
				break
			end
			local _ = table.insert
			local entry = { Name = name, Image = getImage(name) }
			if makeRenderer then
				renderer = makeRenderer(name)
			else
				renderer = makeRenderer
			end
			entry.Render = renderer
			table.insert(items, entry)
		end
		return items
	end

	local function getSelectedCharmName_proto()
		local selected = seasonDropdown.Value
		local charmName
		charmName = not (selected == nil)
		charmName = charmName and charmBySeasonLabel[selected] or nil
		return charmName
	end

	local function parseLeaderboardRank_proto()
		local trimmed = leaderboardRankOptionalEG1TextBox.Value:match("^%s*(.-)%s*$")
		if trimmed == nil or trimmed == "" then
			return nil
		end
		local rank = tonumber(trimmed)
		if rank == nil or rank < 1 then
			return nil
		end
		return (math.floor(rank))
	end

	local function applyRankCharm_proto(...)
		local charmName = getSelectedCharmName()
		if charmName == nil then
			return
		end
		local rank = rankDropdown.Value
		if not rank then
			rank = "Off"
		end
		if rank == "Off" then
			rankCharm:SetForSeason(charmName, nil, nil)
			return
		end
		rankCharm:SetForSeason(charmName, rank, parseLeaderboardRank())
	end

	local function syncRankCharmControls_proto()
		local charmName = getSelectedCharmName()
