	local function buildRankCharmSection_proto(app, grid)
		local AddSection88 = grid.AddSection
		local t371 = { Title = "Rank Charm Override", Side = "right" }
		local rankCharmOverrideSection = AddSection88(grid, t371)
		local seasonOptions = {}
		local charmBySeasonLabel = {}
		local nextSeasonCharm = RankCharms.SEASON_CHARMS
		local index = nil
		while true do
			local seasonCharm
			index, seasonCharm = nextSeasonCharm(nil, index)
			if index == nil then
				break
			end
			local label = string.format(
				"Season %s (%s)",
				tostring(seasonCharm.version),
				tostring(seasonCharm.seasonName)
			)
			table.insert(seasonOptions, label)
			charmBySeasonLabel[label] = seasonCharm.charmName
		end
		local rankOptions = table.create(1)
		local nextRankName = RankCharms.RANK_NAMES
		local index2 = nil
		while true do
			local rankName
			index2, rankName = nextRankName(nil, index2)
			if index2 == nil then
				break
			end
			table.insert(rankOptions, rankName)
		end
		local AddDropdown81 = rankCharmOverrideSection.AddDropdown
		local seasonDropdownOptions = { Label = "Season", Options = seasonOptions, CloseOnSelect = true }
		local seasonDropdown = AddDropdown81(rankCharmOverrideSection, seasonDropdownOptions)
		local AddDropdown82 = rankCharmOverrideSection.AddDropdown
		local rankDropdownOptions = { Label = "Rank", Options = rankOptions, CloseOnSelect = true }
		local rankDropdown = AddDropdown82(rankCharmOverrideSection, rankDropdownOptions)
		local AddTextBox17 = rankCharmOverrideSection.AddTextBox
		local leaderboardRankOptionalEG1TextBoxOptions = { Label = "Leaderboard Rank (optional, e.g. 1)" }
		local leaderboardRankOptionalEG1TextBox = AddTextBox17(rankCharmOverrideSection, leaderboardRankOptionalEG1TextBoxOptions)

		local function getSelectedCharmName()
			local selected = seasonDropdown.Value
			local charmName
			charmName = not (selected == nil)
			charmName = charmName and charmBySeasonLabel[selected] or nil
			return charmName
		end

		local function parseLeaderboardRank()
			local trimmed = leaderboardRankOptionalEG1TextBox.Value:match("^%s*(.-)%s*$")
			if trimmed == nil or trimmed == "" then
				return nil
			end
			local rank = tonumber(trimmed)
			if rank == nil or rank < 1 then
				return nil
			end
			return (math.floor(rank))
		end

		local rankCharm = app.cosmetics:GetRankCharm()

		local function applyRankCharm(...)
			local charmName = getSelectedCharmName()
			if charmName == nil then
				return
			end
			local rank = rankDropdown.Value
			if not rank then
				rank = "Off"
			end
			if rank == "Off" then
				rankCharm:SetForSeason(charmName, nil, nil)
				return
			end
			rankCharm:SetForSeason(charmName, rank, parseLeaderboardRank())
		end

		local function syncRankCharmControls()
			local charmName = getSelectedCharmName()
			if charmName == nil then
				rankDropdown:Set("Off", true)
				leaderboardRankOptionalEG1TextBox:Set("", true)
				return
			end
			local leaderboardRank, rank
			rank, leaderboardRank = rankCharm:GetForSeason(charmName)
			local dropdown = rankDropdown
			local set = dropdown.Set
			if not rank then
				rank = "Off"
			end
			set(dropdown, rank, true)
			local textBox = leaderboardRankOptionalEG1TextBox
			local set2 = textBox.Set
			local text
			text = not (leaderboardRank == nil)
			text = text and tostring(leaderboardRank) or ""
			set2(textBox, text, true)
		end

		seasonDropdown:OnChanged(syncRankCharmControls)
		rankDropdown:OnChanged(applyRankCharm)
		leaderboardRankOptionalEG1TextBox:OnChanged(applyRankCharm)
		return syncRankCharmControls
	end

