			end
			return image
		end

		local function toChoiceValue(displayName)
			if displayName == nil or displayName == "Unselected" then
				return nil
			end
			if displayName == "None" then
				return "NONE_COSMETIC"
			end
			if displayName == "Random" then
				return "RANDOM_COSMETIC"
			end
			return displayName
		end

		local function toDisplayName(value)
			if value == "NONE_COSMETIC" then
				return "None"
			end
			if value == "RANDOM_COSMETIC" then
				return "Random"
			end
			if value == nil then
				return "Unselected"
			end
			return value
		end

