	local function addRemoteEntity(registry, player, entityData)
		local entity = registry._trove:Add(RemoteFighter.new(player, entityData))

		local function onCharacterCreated(...)
			local character = ...
			registry.byModel[character.model] = entity
		end

		entity._trove:Connect(entity.character.created, onCharacterCreated)

		local function onCharacterDied(character)
			registry.byModel[character.model] = nil
		end

		entity._trove:Connect(entity.character.died, onCharacterDied)
		local state = entity.character.state
		if state.alive then
			registry.byModel[state.model] = entity
		end
		local entityAddedSignal = safeIndex(entityData, "EntityAdded")
		local entityRemovedSignal = safeIndex(entityData, "EntityRemoved")

		local function onEntityAdded(...)
			registry.onRemoteEntityAdded:Fire(entity, nil)
		end

		entity._trove:Add(connect(entityAddedSignal, onEntityAdded))

		local function onEntityRemoved(removedEntity)
			registry.onRemoteEntityRemoved:Fire(entity, removedEntity)
		end

		entity._trove:Add(connect(entityRemovedSignal, onEntityRemoved))

		local function onEnemyChanged(isEnemy)
			local enemies = registry.enemies
			local key = player
			repeat
				if isEnemy then
					isEnemy = entity
				end
			until not isEnemy
			enemies[key] = nil
			return
		end

		entity._trove:Connect(entity.enemyChanged, onEnemyChanged)
		registry.byPlayer[player] = entity
		local enemyMap = registry.enemies
		local enemyEntry = entity.enemy
		enemyEntry = enemyEntry and entity or nil
		enemyMap[player] = enemyEntry
		local localState = registry.localState
		if localState ~= nil then
			entity:SetLocalFighter(localState)
		end
		local existingEntity = safeIndex(entityData, "Entity")
		if existingEntity ~= nil then
			registry.onRemoteEntityAdded:Fire(entity, existingEntity)
		end
	end

	local function observeRemoteStates_proto(registry, trove, onAdded, onRemoved)
		local byPlayer = registry.byPlayer
		local player = nil
		while true do
			local fighter
			player, fighter = byPlayer(nil, player)
			if player == nil then
				break
			end
			onAdded(fighter)
		end
		trove:Connect(registry.onRemoteStateAdded, onAdded)
		trove:Connect(registry.onRemoteStateRemoved, onRemoved)
	end

	local function newFighterRegistry_proto(...)
		local trove = Trove.new("fighters")
		local registry = {
			_trove = trove,
			localState = nil,
			byPlayer = {},
			byModel = {},
			enemies = {},
			onLocalStateSet = trove:Add(Signal.new()),
			onLocalStateRemoved = trove:Add(Signal.new()),
