	local function newColorPicker(menu, row, trove, options)
		local gradientMode = options.Gradient
		if not gradientMode then
			gradientMode = "off"
		end
		local default = options.Default
		local rgb = white
		local alpha = 1
		local stops = nil
		if default ~= nil then
			if default.Rgb ~= nil then
				rgb = default.Rgb
			end
			if default.Alpha ~= nil then
				alpha = math.clamp(default.Alpha, 0, 1)
			end
			stops = default.Stops
		end
		local mode = "Solid"
		if not (gradientMode == "off" or
			not (gradientMode == "only" or not (stops == nil or not (0 < #stops)))) then
			mode = "Gradient"
		end
		local ensuredStops = Stops.ensure(stops, rgb)
		local val, sat, hue
		hue, sat, val = rgb:ToHSV()
		local picker = { _trove = trove, _menu = menu, Kind = "ColorPicker", Row = row }
		local alphaEnabled
		alphaEnabled = options.Alpha == true
		picker.AlphaEnabled = alphaEnabled
		picker.Gradient = gradientMode
		picker.Mode = mode
		picker.Hue = hue
		picker.Sat = sat
		picker.Val = val
		picker.Alpha = alpha
		picker.Color = rgb
		picker.Stops = ensuredStops
		picker.ActiveStopIndex = 1
		picker.Dragging = false
		picker._dragMode = nil
		local animatable
		animatable = options.Animatable == true
		picker.Animatable = animatable
		picker.AnimationMode = "None"
		picker.AnimationSpeed = 1
		picker.AnimationBreathingRange = nil
		local value = { Rgb = rgb, Alpha = alpha }
		local valueStops
		valueStops = mode == "Gradient"
		valueStops = valueStops and Stops.clone(ensuredStops) or nil
		value.Stops = valueStops
		picker.Value = value
		picker.Changed = trove:Add(Signal.new())
		picker.ValueChanged = trove:Add(Signal.new())
		picker.AnimationChanged = trove:Add(Signal.new())
		picker.AnimationSpeedChanged = trove:Add(Signal.new())
		picker.AnimationBreathingRangeChanged = trove:Add(Signal.new())
		local changedCallback = options.OnChanged
		if not changedCallback then
			changedCallback = function()
			end
		end
		picker._onChanged = changedCallback
		local allowBreathing
		allowBreathing = options.Alpha == true
		picker._allowBreathing = allowBreathing
		picker._rt = nil
		picker._panel = nil
		picker._popup = nil
		picker._parentOverlay = nil
		local pickerObject = setmetatable(picker, ColorPicker)

		local function attachSwatch(parent, context)
			return (makeSwatch(pickerObject, parent, context))
		end

		row:AttachRight(attachSwatch, 18)
		return pickerObject
	end

