			local entry = { trove = Trove.new(), guarded = nil }
			self._entries[player] = entry

			local function attach()
				local stat = waitForPath(player, (table.create(2)))
				entry.guarded = entry.trove:Add(GuardedValue.new(stat))
				self:_Apply(player)
