	end

	local function setRemotePlayerOverrides_proto(self_, player, overrides, merge)
		self_:_EnsureHooksLoaded()
		local previous = self_._store:GetAll(player)
		if merge then
			local merged = {}
			local item = nil
			while true do
				local selection
				item, selection = previous(nil, item)
				if item == nil then
					break
				end
				merged[item] = selection
