			local item2 = nil
			while true do
				local selection2
				item2, selection2 = overrides(nil, item2)
				if item2 == nil then
					break
				end
				merged[item2] = selection2
			end
			overrides = merged
		end
		self_._store:SetItems(player, overrides)
		self_._remoteViewModelRefresher:RefreshChangedItems(player, previous, overrides)
	end

