			end
			local reacted
			reacted = not (self._reactionElapsed == nil)
			if reacted then
				reacted = config.ReactionTime <= self._reactionElapsed
			end
			if onTarget and reacted then
				self._releaseRemaining = config.ReleaseTime
				startShooting(inner)
