				if index2 == nil then
					break
				end
				entry2.dropdown:Connect(Config.editProfileChanged, refresh)
				entry2.dropdown:Connect(Config:GetPropertyChangedSignal(gunSpecificPath), refresh)
			end
			refresh()
		end

		return bind
	end

