	local function getDueler_proto(duel, player)
		local cached = up0(up0(duel, "_duelers_by_player"), player)
		if cached then
			return cached
		end
		local duelers = up0(duel, "Duelers")
		local index = nil
		while true do
			local dueler
			index, dueler = duelers(nil, index)
			if index == nil then
				break
			end
			if up0(dueler, "Player") == player or getAttribute(dueler, "ObjectID") == player then
				return dueler
			end
		end
		return nil
	end

