			end
			local duelers = up0(duel, "Duelers")
			local index = nil
			while true do
				local dueler
				index, dueler = duelers(nil, index)
				if index == nil then
					break
				end
				if up0(dueler, "Player") == player or getAttribute(dueler, "ObjectID") == player then
					return dueler
				end
			end
			return nil
		end

		return getDueler
	end

