	local function getBoardEntry_proto()
		local settings = Config.data.Misc.PlayerSpoofer.LocalPlayer
		local elo = 0
		if settings.RankedElo.Enabled then
			elo = settings.RankedElo.Value
		else
			local displayElo = LocalPlayer:GetAttribute("DisplayELO")
			if type(displayElo) == "number" then
				elo = displayElo
			end
		end
		local entry = { rank = settings.LeaderboardRank.Value, value = elo }
		return entry
	end

	local function recompute_proto2(hook)
		local spoofer = Config.data.Misc.PlayerSpoofer
		if spoofer.LocalPlayer.LeaderboardRank.Enabled or
			spoofer.OtherPlayers.LeaderboardRank.Enabled then
			hook:Set(getRank)
		else
			hook:Unset()
		end
		if spoofer.LocalPlayer.LeaderboardRank.Enabled then
			hook:SetBoardEntry(getBoardEntry)
		else
			hook:UnsetBoardEntry()
		end
		hook:TriggerRefresh()
	end

	local function destroyLeaderboardRankSpoof_proto(hook)
		hook:Unset()
		hook:UnsetBoardEntry()
		hook:TriggerRefresh()
	end

	local function loadLeaderboardRankSpoof()
		local Config = up0.y()
		up0.hY()
		local LeaderboardRankSpoof = {}
		local getSpoofSettings = up0._()

		local function getRank(player)
			local settings = getSpoofSettings(player)
			local rank = settings.LeaderboardRank.Enabled
			rank = rank and settings.LeaderboardRank.Value or nil
			return rank
		end

		local LocalPlayer = cloneref(game:GetService("Players")).LocalPlayer

		local function getBoardEntry()
			local settings = Config.data.Misc.PlayerSpoofer.LocalPlayer
			local elo = 0
			if settings.RankedElo.Enabled then
				elo = settings.RankedElo.Value
			else
				local displayElo = LocalPlayer:GetAttribute("DisplayELO")
				if type(displayElo) == "number" then
					elo = displayElo
				end
			end
			local entry = { rank = settings.LeaderboardRank.Value, value = elo }
			return entry
		end

		function LeaderboardRankSpoof.recompute(hook)
			local spoofer = Config.data.Misc.PlayerSpoofer
			if spoofer.LocalPlayer.LeaderboardRank.Enabled or
				spoofer.OtherPlayers.LeaderboardRank.Enabled then
				hook:Set(getRank)
			else
				hook:Unset()
			end
			if spoofer.LocalPlayer.LeaderboardRank.Enabled then
				hook:SetBoardEntry(getBoardEntry)
			else
				hook:UnsetBoardEntry()
			end
			hook:TriggerRefresh()
		end

		function LeaderboardRankSpoof.destroy(hook)
			hook:Unset()
			hook:UnsetBoardEntry()
			hook:TriggerRefresh()
		end

		return LeaderboardRankSpoof
	end

