	local function build_proto2(_, menu)
		local addTab = menu.AddTab
		local espTabOptions = {
			Label = "ESP",
			Icon = icons.ESP,
			Description = "Player overlays, bounding boxes, labels, and chams."
		}
		local espTab = addTab(menu, espTabOptions)
		local addTab2 = espTab.AddTab
		local playersTabOptions = {
			Label = "Players",
			Icon = icons.Main,
			Description = "Toggle ESP and configure per-team overlays."
		}
		local playersTab = addTab2(espTab, playersTabOptions)
		local grid = playersTab.Grid
		local gridOptions = { Columns = 2 }
		buildPlayersPage(grid(playersTab, gridOptions), menu)
		local addTab3 = espTab.AddTab
		local soundTabOptions = {
			Label = "Sound",
			Icon = icons.Sound,
			Description = "Sound source visualization and audio indicators."
		}
		local soundTab = addTab3(espTab, soundTabOptions)
		local grid2 = soundTab.Grid
		local gridOptions2 = { Columns = 2 }
		buildSoundPage(grid2(soundTab, gridOptions2))
		local addTab4 = espTab.AddTab
		local appearanceTabOptions = {
			Label = "Appearance",
			Icon = icons.Settings,
