			return false
		end
		state.elapsed = state.elapsed + deltaTime
		local offset = (self_._mapAnchor * self_._startCFrame).Position - self_._aliveState.rootPart.Position
		local flatOffset = Vector3.new(offset.X, 0, offset.Z)
		local distance = flatOffset.Magnitude
		local aligned
		aligned = distance <= Config.data.MovementRecorder.AlignSnapDistance
		if aligned then
			self_._moveHook:SetMoveVector(Vector3.zero)
		else
			self_._moveHook:SetMoveVector(worldToMoveVector(flatOffset.Unit))
		end
		if distance < state.bestDistance - progressEpsilon then
			state.bestDistance = distance
			state.stuckTime = 0
		else
			state.stuckTime = state.stuckTime + deltaTime
		end
		if aligned then
			aligned = lookAligned
		end
		if not aligned then
			aligned = stuckTimeout <= state.stuckTime
		end
		if not aligned then
			return false
		end
		self_._moveHook:SetMoveVector(Vector3.zero)
		local ready = self_:_IsStartItemReady()
		local timedOut
		timedOut = maxAlignTime <= state.elapsed
		if not ready then
			ready = timedOut
		end
		return ready
	end

	local function isStartItemReady_proto(self_)
		if self_._startEquippedIndex == nil then
			return true
		end
		local equipped = self_._itemBehaviors:GetEquipped()
		if equipped == nil or equipped.item.index ~= self_._startEquippedIndex then
			return false
		end
		local cooldownEnd = getField(equipped.item.inner, "_equip_cooldown")
		local cooledDown
		cooledDown = not (type(cooldownEnd) == "number")
		if not cooledDown then
			cooledDown = cooldownEnd <= tick()
		end
		return cooledDown
	end

	local function hasDiverged_proto(self_, offset)
		local positions = self_._positions
		if #positions == 0 then
			return false
		end
		while self_._positionIndex < #positions and
			positions[self_._positionIndex + 1].offset <= offset do
			self_._positionIndex = self_._positionIndex + 1
		end
		local sample = positions[self_._positionIndex]
		local nextSample = positions[self_._positionIndex + 1]
		local alpha, expected
		if nextSample == nil then
			expected = sample.position
		else
			local span = nextSample.offset - sample.offset
			alpha = 0 < span
			alpha = alpha and math.clamp((offset - sample.offset) / span, 0, 1) or 0
			expected = sample.position:Lerp(nextSample.position, alpha)
		end
		local diverged
		diverged = divergeDistance < (self_._mapAnchor:PointToWorldSpace(expected) - self_._aliveState.rootPart.Position).Magnitude
		return diverged
	end

