		local pi9 = math.pi
		local delta = Vector2.new(target.X - current.X, (y - y2 + pi7) % (2 * pi8) - pi9)
		local distance = delta.Magnitude
		if distance <= alignEpsilon then
			return target, true
		end
		return current + delta.Unit * math.min(distance * alpha, maxStep), false
	end

