	local function worldToMoveVector_proto(direction)
		local camera = workspace.CurrentCamera.CFrame
		local flatLook = Vector3.new(camera.LookVector.X, 0, camera.LookVector.Z)
		if flatLook.Magnitude < 0.0001 then
			return Vector3.zero
		end
		return (Vector3.new(
			direction:Dot(Vector3.new(camera.RightVector.X, 0, camera.RightVector.Z).Unit),
			0,
			-direction:Dot(flatLook.Unit)
		))
	end

