			local animateBar = healthBar.AnimateBar
			local animate = healthSettings.Animate
			if animate then
				animate = true
			end
			animateBar(healthBar, animate)
			healthBar:SetValue(75, 100)
			healthBar:SetLabelVisible(settings.HealthNumber.Enabled)
			healthBar:SetVisible(true)
		else
			healthBar:SetVisible(false)
		end
		local ammoBar = self_._ammoBar
